const $=id=>document.getElementById(id);let epoch=0,page=1,timer,active=false;
const node=(tag,text='')=>{const e=document.createElement(tag);e.textContent=text;return e};
const notice=text=>$('notice').textContent=text;
async function api(path,method='GET',data){const r=await fetch(path,{method,headers:{Authorization:'Bearer session','Content-Type':'application/json'},...(data?{body:JSON.stringify(data)}:{})});const d=await r.json();if(!r.ok)throw Error(d.error);return d}
function clear(){active=false;epoch++;clearTimeout(timer);$('workspace').hidden=true;$('login').hidden=false;$('rows').replaceChildren();$('organization').textContent='';$('ticket').reset();$('search').value='';$('page').textContent=''}
async function load(){const id=++epoch,kind=$('kind').value;$('prev').disabled=$('next').disabled=true;$('rows').replaceChildren();try{const d=await api('/api/admin/client-portal?'+new URLSearchParams({kind,page,q:$('search').value}));if(id!==epoch)return;active=true;$('organization').textContent=d.organization;$('workspace').hidden=false;$('login').hidden=true;for(const x of d.items){const a=node('article');a.append(node('h3',x.reference||x.title));if(kind==='contracts')a.append(node('p',x.title+' · '+x.start_date+' — '+x.end_date+' · '+x.status));if(kind==='subscriptions')a.append(node('p',x.title+' · '+x.starts_on+' — '+x.ends_on+' · '+x.status+' · '+x.lifecycle));if(kind==='invoices'){a.append(node('p',x.title+' · '+(x.kind==='SAAS'?'SaaS TTC':'Prestation HT')+' · Échéance '+x.due_date),node('p','Montant '+x.amount+' '+x.currency+' · Réglé '+x.paid+' · Solde '+x.balance));const details=node('details');details.append(node('summary','Règlements'));for(const p of x.payments)details.append(node('p',p.reference+' · '+p.amount+' '+x.currency+' · '+p.paid_on));a.append(details)}if(kind==='tickets')a.append(node('p',x.status+' · '+x.opened_on),node('p',x.request_text));$('rows').append(a)}if(!d.items.length)$('rows').append(node('p','Aucun résultat.'));$('page').textContent='Page '+d.page+' · '+d.total+' élément(s)';$('prev').disabled=d.page===1;$('next').disabled=d.page*10>=d.total;notice('Session client sécurisée.')}catch(e){if(id===epoch){clear();notice(e.message)}}}
function reset(){clearTimeout(timer);epoch++;page=1;if(active)load()}
$('kind').onchange=reset;$('search').oninput=()=>{clearTimeout(timer);epoch++;page=1;$('prev').disabled=$('next').disabled=true;timer=setTimeout(()=>{if(active)load()},200)};
$('prev').onclick=()=>{if(active&&page>1){page--;load()}};$('next').onclick=()=>{if(active&&!$('next').disabled){page++;load()}};
$('ticket').onsubmit=async e=>{e.preventDefault();if(!active)return;const b=e.submitter,id=epoch;b.disabled=true;try{await api('/api/admin/client-portal','POST',Object.fromEntries(new FormData(e.target)));if(active&&id===epoch){e.target.reset();$('kind').value='tickets';page=1;$('search').value='';await load()}}catch(error){if(active&&id===epoch)notice(error.message)}finally{b.disabled=false}};
$('logout').onclick=async()=>{clear();try{await api('/api/auth/logout','POST',{});location.assign('connexion.html')}catch(e){notice('Déconnexion non confirmée : '+e.message)}};
window.addEventListener('pagehide',clear);window.addEventListener('pageshow',e=>{if(e.persisted)load()});load();
